package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;
    // 신용조회 도입 전에 만들어진 대출은 null 이다
    private final CreditCheck creditCheck;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                 CreditCheck creditCheck) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
        this.creditCheck = creditCheck;
    }

    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null,
                Objects.requireNonNull(creditCheck, "creditCheck"));
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt, CreditCheck creditCheck) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    // 반납은 Book.returnBook과 함께 호출된다. 이미 반납된 대출은 다시 반납할 수 없다.
    public void returnBook(LocalDate returnedAt) {
        if (this.returnedAt != null) {
            throw new LoanAlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    // 기한 당일까지는 연체가 아니다. 기한을 넘긴 날짜 수만큼 연체일이 된다. 반납 후에만 호출할 수 있다.
    public long overdueDays() {
        if (returnedAt == null) {
            throw new IllegalStateException("loan is not returned yet: " + id);
        }
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    // Loan 객체 없이 기한과 반납일만으로 연체료를 계산한다. 대출 이력 조회처럼 반납된 대출에만 쓴다
    public static long lateFeeOf(LocalDate dueAt, LocalDate returnedAt) {
        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt)) * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }
}
package com.example.lending.domain;

import java.time.LocalDate;
import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;

    private Book(UUID id, String title, BookStatus status) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    // 신용조회에서 거절된 회원에게는 빌려주지 않는다. 거절되면 책 상태는 바뀌지 않는다
    public Loan loanTo(UUID memberId, LocalDate loanedAt, ReservationQueue reservations, CreditCheck creditCheck) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        if (!reservations.allowsLoanTo(memberId)) {
            throw new ReservedForOtherException(id);
        }
        if (!creditCheck.approved()) {
            throw new CreditRejectedException(memberId);
        }
        Loan loan = Loan.start(id, memberId, loanedAt, creditCheck);
        status = BookStatus.ON_LOAN;
        return loan;
    }

    // 대출 중인 책만 예약할 수 있다. 대출 가능한 책은 바로 빌리면 되고, 폐기된 책은 돌아오지 않는다
    public void checkReservable() {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE) {
            throw new BookAvailableException(id);
        }
    }

    // 훼손되거나 분실된 책을 폐기한다. 대출 중인 책은 반납된 뒤에야 폐기할 수 있다
    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new BookOnLoanException(id);
        }
        status = BookStatus.DISCARDED;
    }

    // 반납 처리 자체는 Loan.returnBook이 맡는다. 여기서는 대출 중인 책만 다시 대출 가능 상태로 바꾼다.
    public void returnBook() {
        if (status != BookStatus.ON_LOAN) {
            throw new IllegalStateException("book is not on loan: " + id);
        }
        status = BookStatus.AVAILABLE;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    // 도서관 후원자. 대출 권수 제한을 받지 않는다
    private static final Set<UUID> UNLIMITED_LOAN_MEMBER_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final UUID id;
    private final String name;
    private boolean suspended;

    private Member(UUID id, String name, boolean suspended) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
        this.suspended = suspended;
    }

    public static Member register(String name) {
        return register(UUID.randomUUID(), name);
    }

    public static Member register(UUID id, String name) {
        return new Member(id, name, false);
    }

    public static Member reconstitute(UUID id, String name, boolean suspended) {
        return new Member(id, name, suspended);
    }

    // 연체가 잦은 회원의 대출을 막는다. 이미 정지된 회원에게 다시 정지해도 상태는 그대로다
    public void suspend() {
        suspended = true;
    }

    public void unsuspend() {
        suspended = false;
    }

    public void checkCanBorrow(long activeLoanCount) {
        if (suspended) {
            throw new MemberSuspendedException(id);
        }
        if (UNLIMITED_LOAN_MEMBER_IDS.contains(id)) {
            return;
        }
        if (activeLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public boolean isSuspended() {
        return suspended;
    }
}

