public record AuditLog(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {

    public AuditLog {
        Objects.requireNonNull(action, "action");
        Objects.requireNonNull(targetId, "targetId");
        Objects.requireNonNull(occurredAt, "occurredAt");
    }

    public static AuditLog now(AuditAction action, UUID targetId, UUID memberId) {
        return new AuditLog(action, targetId, memberId, Instant.now());
    }
}

