package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadAuditLogsPort;
import com.example.lending.application.port.out.SaveAuditLogPort;
import com.example.lending.domain.AuditLog;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class AuditLogPersistenceAdapter implements SaveAuditLogPort, LoadAuditLogsPort {

    private final AuditLogJpaRepository auditLogJpaRepository;

    public AuditLogPersistenceAdapter(AuditLogJpaRepository auditLogJpaRepository) {
        this.auditLogJpaRepository = auditLogJpaRepository;
    }

    @Override
    public void saveAuditLog(AuditLog auditLog) {
        auditLogJpaRepository.save(new AuditLogJpaEntity(auditLog.action(), auditLog.targetId(),
                auditLog.memberId(), auditLog.occurredAt()));
    }

    @Override
    public List<AuditLog> loadAuditLogs(UUID targetId) {
        return auditLogJpaRepository.findByTargetIdOrderByOccurredAtAscSeqAsc(targetId).stream()
                .map(e -> new AuditLog(e.getAction(), e.getTargetId(), e.getMemberId(), e.getOccurredAt()))
                .toList();
    }
}

